int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    // Each element gets a unique id; both heaps hold (value, id) and skip ids no longer alive.
    vector<long long> val(2 * n);
    vector<char> alive(2 * n, 1);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> small;
    priority_queue<pair<long long, int>> large;
    for (int i = 0; i < n; i++) {
        cin >> val[i];
        small.push({val[i], i});
        large.push({val[i], -i});
    }
    long long cost = 0;
    for (int id = n; id < 2 * n - 1; id++) {
        while (!alive[small.top().second]) small.pop();
        auto [low, i] = small.top();
        small.pop();
        alive[i] = 0;
        while (!alive[-large.top().second]) large.pop();
        auto [high, j] = large.top();
        large.pop();
        alive[-j] = 0;
        long long value = low + high, den = high - low + 1;
        // Exact ceiling division for a positive denominator, also for negative numerators.
        long long q = value / den;
        if (value % den != 0 && value > 0) q++;
        cost += q;
        val[id] = value;
        small.push({value, id});
        large.push({value, -id});
    }
    cout << cost << "\n";
}

import java.io.*;
