public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) next();
        // Each element gets a unique id; both heaps hold ids and skip ids no longer alive.
        long[] val = new long[2 * n];
        boolean[] dead = new boolean[2 * n];
        PriorityQueue<Integer> small = new PriorityQueue<>((x, y) -> val[x] != val[y] ? Long.compare(val[x], val[y]) : Integer.compare(x, y));
        PriorityQueue<Integer> large = new PriorityQueue<>((x, y) -> val[x] != val[y] ? Long.compare(val[y], val[x]) : Integer.compare(x, y));
        for (int i = 0; i < n; i++) {
            val[i] = next();
            small.add(i);
            large.add(i);
        }
        long cost = 0;
        for (int id = n; id < 2 * n - 1; id++) {
            while (dead[small.peek()]) small.poll();
            int i = small.poll();
            dead[i] = true;
            while (dead[large.peek()]) large.poll();
            int j = large.poll();
            dead[j] = true;
            long low = val[i], high = val[j];
            long value = low + high, den = high - low + 1;
            cost += -Math.floorDiv(-value, den);
            val[id] = value;
            small.add(id);
            large.add(id);
        }
        System.out.println(cost);
    }
}

