var data []byte
var pos int

func next() int64 {
	for data[pos] != '-' && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	neg := data[pos] == '-'
	if neg {
		pos++
	}
	var x int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		x = x*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -x
	}
	return x
}

var val []int64

// idHeap orders element ids by value (descending when maxFirst), ties by id.
type idHeap struct {
	ids      []int
	maxFirst bool
}

func (h *idHeap) Len() int { return len(h.ids) }
func (h *idHeap) Less(a, b int) bool {
	x, y := h.ids[a], h.ids[b]
	if val[x] != val[y] {
		return (val[x] < val[y]) != h.maxFirst
	}
	return x < y
}
func (h *idHeap) Swap(a, b int) { h.ids[a], h.ids[b] = h.ids[b], h.ids[a] }
func (h *idHeap) Push(x any)    { h.ids = append(h.ids, x.(int)) }
func (h *idHeap) Pop() any {
	last := h.ids[len(h.ids)-1]
	h.ids = h.ids[:len(h.ids)-1]
	return last
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(next())
	// Each element gets a unique id; both heaps hold ids and skip ids no longer alive.
	val = make([]int64, 2*n)
	dead := make([]bool, 2*n)
	small := &idHeap{}
	large := &idHeap{maxFirst: true}
	for i := 0; i < n; i++ {
		val[i] = next()
		small.ids = append(small.ids, i)
		large.ids = append(large.ids, i)
	}
	heap.Init(small)
	heap.Init(large)
	var cost int64
	for id := n; id < 2*n-1; id++ {
		for dead[small.ids[0]] {
			heap.Pop(small)
		}
		i := heap.Pop(small).(int)
		dead[i] = true
		for dead[large.ids[0]] {
			heap.Pop(large)
		}
		j := heap.Pop(large).(int)
		dead[j] = true
		low, high := val[i], val[j]
		value, den := low+high, high-low+1
		// Exact ceiling division for a positive denominator, also for negative numerators.
		q := value / den
		if value%den != 0 && value > 0 {
			q++
		}
		cost += q
		val[id] = value
		heap.Push(small, id)
		heap.Push(large, id)
	}
	fmt.Println(cost)
}
